package org.apache.pinot.verifier;

import java.nio.file.Path;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import java.util.stream.Collectors;
import org.apache.maven.enforcer.rule.api.EnforcerRule;
import org.apache.maven.enforcer.rule.api.EnforcerRuleException;
import org.apache.maven.enforcer.rule.api.EnforcerRuleHelper;
import org.apache.maven.execution.MavenSession;
import org.apache.maven.model.Dependency;
import org.apache.maven.model.DependencyManagement;
import org.apache.maven.model.Model;
import org.apache.maven.project.MavenProject;


/**
 * A custom Maven Enforcer rule that centralizes dependency version management for the Apache Pinot project.
 *
 * <p>The rule enforces the following policies:
 * <ul>
 *   <li>The root POM may only declare dependency versions inside {@code <dependencyManagement>} and those versions
 *       must be expressed through property placeholders (i.e. they must start with {@code ${}).</li>
 *   <li>Non-root modules (unless explicitly skipped) must not declare a version for any of their direct
 *       dependencies; the version is expected to be inherited from the root POM.</li>
 * </ul>
 *
 * <p>See the
 * <a href="https://docs.pinot.apache.org/developers/developers-and-contributors/dependency-management">dependency
 * management documentation</a> for the best practice.
 */
public class PinotCustomDependencyVersionRule implements EnforcerRule {
  private List<String> _skipModuleList;

  public PinotCustomDependencyVersionRule() {
  }

  public PinotCustomDependencyVersionRule(String skipModules) {
    setSkipModules(skipModules);
  }

  public void setSkipModules(String skipModules) {
    if (skipModules == null || skipModules.isBlank()) {
      _skipModuleList = new ArrayList<>();
    } else {
      _skipModuleList = Arrays.stream(skipModules.split(","))
          .map(String::trim)
          .filter(s -> !s.isEmpty())
          .collect(Collectors.toList());
    }
  }

  @Override
  public void execute(EnforcerRuleHelper helper)
      throws EnforcerRuleException {
    MavenProject project;
    MavenSession session;
    try {
      project = (MavenProject) helper.evaluate("${project}");
      session = (MavenSession) helper.evaluate("${session}");
    } catch (Exception e) {
      throw new EnforcerRuleException("Unable to retrieve MavenProject", e);
    }

    Model model = project.getOriginalModel();

    if (project.isExecutionRoot()) {
      // Root POM: versions may only appear inside <dependencyManagement> and must use property placeholders.
      DependencyManagement dependencyManagement = model.getDependencyManagement();
      if (dependencyManagement == null || dependencyManagement.getDependencies() == null) {
        return;
      }
      for (Dependency dependency : dependencyManagement.getDependencies()) {
        String version = dependency.getVersion();
        if (version != null && !version.trim().startsWith("${")) {
          throw new EnforcerRuleException(String.format(
              "Root POM has hardcoded version '%s' in <dependencyManagement> for %s:%s. Please refer to "
                  + "https://docs.pinot.apache.org/developers/developers-and-contributors/dependency-management "
                  + "for the best practice",
              dependency.getVersion(), dependency.getGroupId(), dependency.getArtifactId()));
        }
      }

      List<Dependency> rootDependencies = model.getDependencies();
      if (rootDependencies != null && !rootDependencies.isEmpty()) {
        for (Dependency dependency : rootDependencies) {
          throw new EnforcerRuleException(String.format(
              "Root POM defines a dependency (%s:%s) outside <dependencyManagement>. Please refer to "
                  + "https://docs.pinot.apache.org/developers/developers-and-contributors/dependency-management "
                  + "for the best practice",
              dependency.getGroupId(), dependency.getArtifactId()));
        }
      }
      return;
    }

    // Non-root module: skip enforcement if this module is part of the configured skip list.
    if (_skipModuleList != null && !_skipModuleList.isEmpty()) {
      Path topLevelBaseDir = session.getTopLevelProject().getBasedir().toPath().toAbsolutePath().normalize();
      Path currentBaseDir = project.getBasedir().toPath().toAbsolutePath().normalize();
      Path relativePath = topLevelBaseDir.relativize(currentBaseDir);
      String topLevelModule = relativePath.getNameCount() > 0 ? relativePath.getName(0).toString() : "";
      for (String skipModule : _skipModuleList) {
        if (topLevelModule.equals(skipModule)) {
          return;
        }
      }
    }

    // Non-root module: no direct dependency may declare a version, whether literal or property-based.
    List<Dependency> dependencies = model.getDependencies();
    for (Dependency dependency : dependencies) {
      if (dependency.getVersion() != null) {
        throw new EnforcerRuleException(String.format(
            "Module '%s' declares version '%s' for dependency %s:%s. Please refer to "
                + "https://docs.pinot.apache.org/developers/developers-and-contributors/dependency-management "
                + "for the best practice",
            project.getArtifactId(), dependency.getVersion(), dependency.getGroupId(),
            dependency.getArtifactId()));
      }
    }
  }

  @Override
  public String getCacheId() {
    return String.format("skipModuleList=%s", _skipModuleList);
  }

  @Override
  public boolean isCacheable() {
    return true;
  }

  @Override
  public boolean isResultValid(EnforcerRule cachedRule) {
    return false;
  }
}
